using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.Z },
        new SkillSlot { keyBinding = KeyCode.X },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（槽位 0~3，留空则不装备）")]
    [SerializeField] private string _initialSkillId0;
    [SerializeField] private string _initialSkillId1;
    [SerializeField] private string _initialSkillId2;
    [SerializeField] private string _initialSkillId3;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkills();
    }

    private void EquipInitialSkills()
    {
        var ids = new[] { _initialSkillId0, _initialSkillId1, _initialSkillId2, _initialSkillId3 };
        for (int i = 0; i < ids.Length; i++)
        {
            if (!string.IsNullOrEmpty(ids[i]))
                EquipSkill(i, ids[i]);
        }
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>按 skillId 刷新技能冷却（完美格挡等效果使用）</summary>
    public void ResetCooldownBySkillId(string skillId)
    {
        foreach (var slot in _slots)
        {
            if (slot.Skill != null && slot.Skill.Data.skillId == skillId)
            {
                slot.Skill.ResetCooldown();
                return;
            }
        }
    }

    /// <summary>
    /// 刷新剩余冷却时间最长的技能（细胞部分重编程等效果使用）。
    /// 返回被刷新的技能实例；无冷却中的技能时返回 null。
    /// </summary>
    public SkillInstance ResetLongestCooldownSkill(string excludeSkillId = null)
    {
        SkillInstance longest = null;
        foreach (var slot in _slots)
        {
            var skill = slot.Skill;
            if (skill == null || !skill.IsCoolingDown) continue;
            // 排除自身（施放中的技能不应刷新自己的冷却）
            if (excludeSkillId != null && skill.Data.skillId == excludeSkillId) continue;
            if (longest == null || skill.CooldownRemaining > longest.CooldownRemaining)
                longest = skill;
        }

        if (longest != null)
            longest.ResetCooldown();
        return longest;
    }

    /// <summary>按 skillId 查找绑定键位（长按技能等效果使用）</summary>
    public KeyCode GetKeyCodeBySkillId(string skillId)
    {
        foreach (var slot in _slots)
        {
            if (slot.Skill != null && slot.Skill.Data.skillId == skillId)
                return slot.keyBinding;
        }
        return KeyCode.None;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    /// <summary>投射物阵营（公开只读，供地面区域等组件读取）</summary>
    public OwnerType Owner => _owner;

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <summary>是否被时停冻结</summary>
    public bool IsFrozen { get; private set; }
    private float _frozenLifetimeRemain;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;
        IsFrozen = false;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>冻结投射物（停止移动+暂停生命周期）</summary>
    public void Freeze()
    {
        if (!_isInitialized || IsFrozen) return;
        IsFrozen = true;
        // 记录剩余生命时间并取消自动回收
        _frozenLifetimeRemain = Mathf.Max(lifeTime * 0.5f, 1f);
        CancelInvoke(nameof(ReturnToPool));
    }

    /// <summary>解冻投射物，恢复移动和生命周期</summary>
    public void Unfreeze()
    {
        if (!_isInitialized || !IsFrozen) return;
        IsFrozen = false;
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), _frozenLifetimeRemain);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized || IsFrozen) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";

        // 动情腺溢散（互相攻击）：敌人投射物命中其他敌人时，若目标带混淆 debuff 则也造成伤害
        bool confusionHit = false;
        if (_owner == OwnerType.Enemy && other.CompareTag("Enemy"))
        {
            var buffMgr = other.GetComponent<BuffManager>();
            confusionHit = buffMgr != null && buffMgr.HasBuff("gland_confusion");
        }

        if (!other.CompareTag(targetTag) && !confusionHit) return;

        // 护盾拦截：目标架盾中则挡住弹幕（不造成伤害）
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
            ReturnToPool();
            return;
        }

        // 因子掠夺：命中目标后先偷取其增益 buff（目标存活时才有 buff 可偷）
        var plunder = GetComponent<BuffPlunderOnHit>();
        if (plunder != null)
            plunder.TryPlunder(other.gameObject);

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 投射物对象池 — 按 prefab 分组，池化复用 GameObject。
/// </summary>
public static class ProjectilePool
{
    private static readonly Dictionary<int, Queue<GameObject>> _pools = new();

    /// <summary>从池中取出，池空则 Instantiate，自动标记来源 prefab</summary>
    public static GameObject Get(GameObject prefab, Vector3 position, Quaternion rotation)
    {
        int key = prefab.GetInstanceID();
        if (!_pools.TryGetValue(key, out var queue))
            queue = _pools[key] = new Queue<GameObject>();

        GameObject obj;
        if (queue.Count > 0)
        {
            obj = queue.Dequeue();
            var t = obj.transform;
            t.position = position;
            t.rotation = rotation;
            obj.SetActive(true);
        }
        else
        {
            obj = Object.Instantiate(prefab, position, rotation);
            obj.name = prefab.name;
            // 贴上来源标记
            var marker = obj.AddComponent<PoolMarker>();
            marker.prefabId = key;
        }

        foreach (var p in obj.GetComponents<IPoolable>())
            p.OnSpawn();

        return obj;
    }

    /// <summary>归还实例到池（停用+入队）</summary>
    public static void Return(GameObject instance)
    {
        if (instance == null) return;

        foreach (var p in instance.GetComponents<IPoolable>())
            p.OnReturn();

        instance.transform.SetParent(null);
        instance.SetActive(false);

        var marker = instance.GetComponent<PoolMarker>();
        if (marker != null)
        {
            int key = marker.prefabId;
            if (!_pools.TryGetValue(key, out var queue))
                queue = _pools[key] = new Queue<GameObject>();
            queue.Enqueue(instance);
        }
        else
        {
            Object.Destroy(instance);
        }
    }

    /// <summary>预热（pool 已有同级实例则跳过）</summary>
    public static int Prewarm(GameObject prefab, int count)
    {
        int key = prefab.GetInstanceID();
        if (!_pools.TryGetValue(key, out var queue))
            queue = _pools[key] = new Queue<GameObject>();

        int created = 0;
        while (queue.Count < count && created < count)
        {
            var obj = Object.Instantiate(prefab);
            obj.name = prefab.name;
            obj.SetActive(false);
            queue.Enqueue(obj);
            if (obj.GetComponent<PoolMarker>() == null)
                obj.AddComponent<PoolMarker>().prefabId = key;
            created++;
        }
        return created; // 实际创建数（已存在则不创建）
    }

    /// <summary>清空</summary>
    public static void Clear()
    {
        foreach (var q in _pools.Values)
            while (q.Count > 0) Object.Destroy(q.Dequeue());
        _pools.Clear();
    }
}

/// <summary>池化生命周期回调</summary>
public interface IPoolable
{
    void OnSpawn();      // Get 取出时
    void OnReturn();     // Return 归还前
}

/// <summary>内部标记：记录此对象源自哪个 prefab</summary>
public class PoolMarker : MonoBehaviour
{
    public int prefabId;
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 召唤技能：在施法者周围随机位置生成单位。
/// 根据施法者阵营自动选择预制体池、Tag 与目标。
/// </summary>
[CreateAssetMenu(fileName = "SummonEffect", menuName = "Game/Skill Effect/Summon")]
public class SummonSkillEffect : SkillEffectBase
{
    [Header("召唤 — 敌方单位池（Boss/Enemy 释放时使用）")]
    [Tooltip("生成的单位 Tag=Enemy，攻击玩家")]
    public GameObject[] enemyMinionPrefabs;

    [Header("召唤 — 友方单位池（Player 释放时使用）")]
    [Tooltip("生成的单位 Tag=Player，攻击敌人")]
    public GameObject[] playerMinionPrefabs;

    [Header("参数")]
    [Tooltip("召唤数量")]
    public int count = 3;

    [Tooltip("生成半径 (围绕施法者)")]
    public float spawnRadius = 4f;

    [Tooltip("生成间隔 (秒)")]
    public float spawnInterval = 0.3f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;
        mono.StartCoroutine(SummonRoutine(caster, ownerType));
    }

    private System.Collections.IEnumerator SummonRoutine(ISkillCaster caster, Projectile.OwnerType ownerType)
    {
        GameObject[] pool = ownerType == Projectile.OwnerType.Player
            ? playerMinionPrefabs
            : enemyMinionPrefabs;

        if (pool == null || pool.Length == 0)
        {
            Debug.LogWarning("SummonSkillEffect: 无可用预制体池");
            yield break;
        }

        string targetTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        string selfTag   = ownerType == Projectile.OwnerType.Player ? "Player" : "Enemy";

        Vector2 center = caster.CasterTransform.position;
        Transform parent = caster.CasterTransform.parent;

        for (int i = 0; i < count; i++)
        {
            Vector2 offset = Random.insideUnitCircle * spawnRadius;
            Vector2 spawnPos = center + offset;

            GameObject prefab = pool[Random.Range(0, pool.Length)];
            if (prefab == null) continue;

            var go = Object.Instantiate(prefab, spawnPos, Quaternion.identity, parent);
            go.name = $"Summon_{ownerType}_{i}_{prefab.name}";

            // 阵营标记
            go.tag = selfTag;

            // 设置敌人 Core 的初始目标
            var core = go.GetComponent<EnemyCore>();
            if (core != null)
            {
                var target = FindNearestTarget(spawnPos, targetTag);
                if (target != null)
                    core.PlayerTarget = target; // 字段名是 PlayerTarget，但实际是"攻击目标"
            }

            yield return new WaitForSeconds(spawnInterval);
        }
    }

    private static Transform FindNearestTarget(Vector2 origin, string targetTag)
    {
        var gos = GameObject.FindGameObjectsWithTag(targetTag);
        if (gos == null || gos.Length == 0) return null;

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in gos)
        {
            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("货币掉落")]
    [SerializeField] private int _currencyPerEnemy = 3;
    [SerializeField] private Sprite _currencyIcon;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        // 自动加载货币图标
        if (_currencyIcon == null)
            _currencyIcon = Resources.Load<Sprite>("TestAssets/Icons/icon_atp");

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = roomRoot.config.maxEnemies == 0? true : false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        // Shop 房间特殊处理：开张商店
        if (roomRoot.config.roomType == RoomType.Shop)
        {
            if (_isFirstEnter)
            {
                _isFirstEnter = false;
                OpenShopRoom();
            }
            return;
        }

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;

            // 统计：首次进入房间
            GameStatistics.Instance?.RecordRoomVisited(roomRoot.config.roomType);

            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
            else
            {
                // 无怪物的房间（如 Start 房）：直接生成道具
                SpawnItems();
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 道具现在是普通 ItemPickup，离开后保留在地图中
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)，跳过隐藏墙</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null && portal.HiddenWallHP <= 0)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;
        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        // 生成货币掉落
        SpawnCurrency(enemy.transform.position, _currencyPerEnemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();

        // 激活相邻隐藏房的门 (变为可破坏状态)
        ActivateHiddenWalls();

        // 生成道具奖励
        SpawnItems();

        // Boss/Exit 房生成下一层出口
        TrySpawnNextLevelExit();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");

        // 统计：清空房间
        GameStatistics.Instance?.RecordRoomCleared(roomRoot.config.roomType);

        OnRoomCleared?.Invoke();
    }

    /// <summary>Boss/Exit 房清空后在房间中心生成下一层出口</summary>
    private void TrySpawnNextLevelExit()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var roomType = roomRoot.config.roomType;
        if (roomType != RoomType.Boss && roomType != RoomType.Exit) return;

        var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
        if (mapConfigAsset == null) return;

        var exitGo = Instantiate(mapConfigAsset.nextLevelExitPrefab, roomRoot.Center, Quaternion.identity, transform);
        exitGo.name = "NextLevelExit";

        var exitComp = exitGo.GetComponent<NextLevelExit>();
        if (exitComp == null)
        {
            Debug.LogError("RoomManager: nextLevelExitPrefab 上没有挂载 NextLevelExit 组件，请在预制体上添加该脚本");
            return;
        }
        exitComp.nextSceneName = mapConfigAsset.nextSceneName;

        Debug.Log($"RoomManager: 房间 {roomRoot.roomId} 生成下一层出口 -> {mapConfigAsset.nextSceneName}");
    }

    /// <summary>激活通往相邻隐藏房的门</summary>
    private void ActivateHiddenWalls()
    {
        if (roomRoot == null) return;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph == null) return;

        var node = graph.GetNode(roomRoot.roomId);
        if (node == null) return;

        foreach (var conn in node.connections)
        {
            var targetNode = graph.GetNode(conn.Key);
            if (targetNode == null || targetNode.roomType != RoomType.Hidden) continue;

            // 找到指向隐藏房的门 Portal
            var portals = GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                if (portal.targetRoomId == conn.Key && portal.HiddenWallHP > 0)
                {
                    portal.SetBreakable();
                    break;
                }
            }
        }
    }

    /// <summary>生成道具</summary>
    private void SpawnItems()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;
        if (cfg.itemPool == null || cfg.itemPool.Count == 0) return;

        int totalItems = Random.Range(cfg.minItems, cfg.maxItems + 1);
        int spawnPointCount = roomRoot.itemSpawnPoints != null ? roomRoot.itemSpawnPoints.Length : 0;
        if (spawnPointCount == 0) return;

        int spawnCount = Mathf.Min(totalItems, spawnPointCount);

        for (int i = 0; i < spawnCount; i++)
        {
            int idx = Random.Range(0, cfg.itemPool.Count);
            var itemPrefab = cfg.itemPool[idx];
            if (itemPrefab == null) continue;

            Instantiate(itemPrefab, roomRoot.itemSpawnPoints[i].position, Quaternion.identity, transform);
        }
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    // ==================== Shop 房间 ====================

    /// <summary>开张商店</summary>
    private void OpenShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager == null)
        {
            Debug.LogWarning($"[RoomManager] Room{roomRoot.roomId}: Shop 房间但未挂载 ShopManager 组件");
            return;
        }

        shopManager.OpenShop();
    }

    /// <summary>打烊商店</summary>
    private void CloseShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager != null)
            shopManager.CloseShop();
    }

    /// <summary>在指定位置生成货币掉落物</summary>
    private void SpawnCurrency(Vector3 position, int amount)
    {
        var go = new GameObject("CurrencyPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(CurrencyPickup));

        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = _currencyIcon;
        sr.sortingOrder = 5;

        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.4f;

        var pickup = go.GetComponent<CurrencyPickup>();
        pickup.amount = amount;

        // 随机散布
        position += (Vector3)(Random.insideUnitCircle * 0.5f);
        go.transform.position = position;
        go.transform.SetParent(transform);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图管理器 (单例) — 新地图系统的核心管理器。
/// 替代旧的 TileManager。
/// 负责: 地图生成、房间实例化、房间切换、玩家追踪。
/// </summary>
public class MapManager : MonoBehaviour
{
    public static MapManager Instance { get; private set; }

    [Header("地图配置")]
    [SerializeField] private MapConfig _mapConfig;

    [Header("运行时")]
    [SerializeField] private int _currentRoomId;
    [SerializeField] private bool _isSwitchingRoom;

    // 内部状态
    private RoomGraph _roomGraph;
    private MapGenerator _generator;
    private Dictionary<int, RoomRoot> _roomInstances = new();
    private RoomRoot _currentRoom;
    private Coroutine _switchCoroutine;
    private Transform _playerTransform;

    /// <summary>玩家从门进入新房间时的内缩距离 (避免立刻再次触发门)</summary>
    [SerializeField] private float _doorEntryOffset = 0f;

    // 事件
    public event System.Action<int, int> OnRoomChanged; // (fromRoomId, toRoomId)
    public event System.Action<int, int> OnRoomSwitchStarted;
    public event System.Action<int> OnRoomSwitchCompleted; // (newRoomId)

    // 属性
    public RoomRoot CurrentRoom => _currentRoom;
    public int CurrentRoomId => _currentRoomId;
    public bool IsSwitchingRoom => _isSwitchingRoom;
    public RoomGraph RoomGraph => _roomGraph;
    public MapConfig MapConfigAsset => _mapConfig;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    private void Start()
    {
        // 缓存玩家 Transform
        var playerGo = GameObject.FindGameObjectWithTag("Player");
        if (playerGo != null)
            _playerTransform = playerGo.transform;

        if (_mapConfig != null)
        {
            GenerateMap();
        }
        else
        {
            Debug.LogError("MapManager: MapConfig 未配置!");
        }
    }

    // ==================== 地图生成 ====================

    /// <summary>生成并实例化地图</summary>
    public void GenerateMap()
    {
        if (_mapConfig == null)
        {
            Debug.LogError("MapManager: MapConfig 为空，无法生成地图");
            return;
        }

        // 清理旧实例
        ClearExistingRooms();

        // 设置随机种子
        int seed = _mapConfig.useRandomSeed ? Random.Range(0, int.MaxValue) : _mapConfig.seed;

        // 生成房间图
        _generator = new MapGenerator(_mapConfig);
        _roomGraph = _generator.Generate(seed);

        // 实例化所有房间
        foreach (var node in _roomGraph.nodes)
        {
            InstantiateRoom(node);
        }

        // 设置所有 RoomPortal 的目标房间
        SetupPortals();

        // 先隐藏所有房间
        foreach (var room in _roomInstances.Values)
        {
            room.Deactivate();
        }

        // 激活起始房间
        var startNode = _roomGraph.GetNode(_roomGraph.startRoomId);
        if (startNode != null && _roomInstances.TryGetValue(_roomGraph.startRoomId, out var startRoom))
        {
            startRoom.Activate();
            _currentRoomId = startRoom.roomId;
            _currentRoom = startRoom;

            // 通知 RoomManager 玩家进入
            var roomMgr = startRoom.GetComponent<RoomManager>();
            if (roomMgr != null)
                roomMgr.OnPlayerEnter();
        }

        Debug.Log($"MapManager: 地图生成完成 — {_roomGraph.nodes.Count} 个房间, Start={_roomGraph.startRoomId}");
    }

    /// <summary>实例化单个房间</summary>
    private void InstantiateRoom(RoomNode node)
    {
        var prefab = node.config.GetRandomPrefab();
        if (prefab == null)
        {
            Debug.LogError($"MapManager: RoomConfig '{node.config.name}' 没有预制体!");
            return;
        }

        var go = Instantiate(prefab, node.worldPosition, Quaternion.identity, transform);
        go.name = $"Room_{node.roomId}_{node.roomType}";

        var root = go.GetComponent<RoomRoot>();
        if (root == null)
        {
            root = go.AddComponent<RoomRoot>();
        }

        root.config = node.config;
        root.roomId = node.roomId;

        // 确保有 RoomManager
        var roomMgr = go.GetComponent<RoomManager>();
        if (roomMgr == null)
            go.AddComponent<RoomManager>();

        _roomInstances[node.roomId] = root;
    }

    /// <summary>设置所有门的连接目标；无连接的门伪装为墙壁。</summary>
    private void SetupPortals()
    {
        foreach (var node in _roomGraph.nodes)
        {
            if (!_roomInstances.TryGetValue(node.roomId, out var root))
                continue;

            var portals = root.GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                // 查找匹配的连接
                bool connected = false;
                foreach (var conn in node.connections)
                {
                    if (conn.Value == portal.direction)
                    {
                        portal.targetRoomId = conn.Key;

                        // 如果目标房间是隐藏房，设置为可破坏墙壁
                        var targetNode = _roomGraph.GetNode(conn.Key);
                        if (targetNode != null && targetNode.roomType == RoomType.Hidden)
                        {
                            int hp = targetNode.config.hiddenWallHP > 0 ? targetNode.config.hiddenWallHP : 4;
                            portal.SetAsBreakableWall(hp);
                        }

                        connected = true;
                        break;
                    }
                }

                if (!connected)
                {
                    portal.HideAsWall();
                }
            }
        }
    }

    // ==================== 房间切换 ====================

    /// <summary>切换到目标房间，玩家从指定方向的门进入</summary>
    public void SwitchRoom(int targetRoomId, DoorDirection entryDir)
    {
        if (_isSwitchingRoom) return;
        if (targetRoomId == _currentRoomId) return;
        if (!_roomInstances.TryGetValue(targetRoomId, out var targetRoom)) return;

        StartCoroutine(SwitchRoomRoutine(targetRoomId, targetRoom, entryDir));
    }

    private IEnumerator SwitchRoomRoutine(int targetRoomId, RoomRoot targetRoom, DoorDirection entryDir)
    {
        _isSwitchingRoom = true;
        int fromRoomId = _currentRoomId;

        OnRoomSwitchStarted?.Invoke(fromRoomId, targetRoomId);

        // 通知旧房间玩家离开
        if (_currentRoom != null)
        {
            var oldMgr = _currentRoom.GetComponent<RoomManager>();
            oldMgr?.OnPlayerExit();
        }

        // 激活新房间
        targetRoom.Activate();

        // 传送玩家到目标房间入口 (反方向门的内侧)
        DoorDirection targetEntryDir = RoomConfig.OppositeDir(entryDir);
        TeleportPlayerToDoor(targetRoom, targetEntryDir);

        // 通知新房间玩家进入
        var newMgr = targetRoom.GetComponent<RoomManager>();
        newMgr?.OnPlayerEnter();

        // 更新状态
        _currentRoom = targetRoom;
        _currentRoomId = targetRoomId;

        // 等待摄像机过渡完成
        var cameraCtrl = Camera.main != null ? Camera.main.GetComponent<RoomCameraController>() : null;
        if (cameraCtrl != null)
        {
            bool transitionDone = false;
            cameraCtrl.MoveToRoom(targetRoom, () => transitionDone = true);
            yield return new WaitUntil(() => transitionDone);
        }

        // 隐藏旧房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Key != _currentRoomId)
                kvp.Value.Deactivate();
        }

        _isSwitchingRoom = false;
        OnRoomChanged?.Invoke(fromRoomId, targetRoomId);
        OnRoomSwitchCompleted?.Invoke(targetRoomId);

        // 统计：访问房间已由 RoomManager.OnPlayerEnter（_isFirstEnter 守卫）负责，此处不再重复

        Debug.Log($"MapManager: 切换到房间 {targetRoomId} ({targetRoom.config.roomType})");
    }

    /// <summary>将玩家传送到目标房间入口门内侧的地板中央位置</summary>
    private void TeleportPlayerToDoor(RoomRoot room, DoorDirection entryDir)
    {
        if (_playerTransform == null)
        {
            var playerGo = GameObject.FindGameObjectWithTag("Player");
            if (playerGo != null) _playerTransform = playerGo.transform;
        }
        if (_playerTransform == null) return;

        // 玩家从 entryDir 方向的门进入，放置在距离墙壁 _doorEntryOffset 格的位置
        Vector2 halfSize = room.roomSize * 0.5f;
        float offset = halfSize.y - _doorEntryOffset;
        if (entryDir is DoorDirection.Left or DoorDirection.Right)
            offset = halfSize.x - _doorEntryOffset;

        // 玩家从 entryDir 方向的门进入，放置在房间中心朝入口门方向偏移
        Vector2 doorDir = entryDir switch
        {
            DoorDirection.Top => Vector2.up,
            DoorDirection.Bottom => Vector2.down,
            DoorDirection.Left => Vector2.left,
            DoorDirection.Right => Vector2.right,
            _ => Vector2.zero
        };

        Vector2 targetPos = room.Center + doorDir * offset;

        TeleportRigidbody(_playerTransform, targetPos);
        TeleportFollowers(targetPos, doorDir, room.transform);
    }

    /// <summary>安全传送 Transform（优先通过 Rigidbody2D.position）</summary>
    private static void TeleportRigidbody(Transform t, Vector2 targetPos)
    {
        if (t == null) return;
        var rb = t.GetComponent<Rigidbody2D>();
        if (rb != null)
        {
            rb.velocity = Vector2.zero;
            rb.position = targetPos;
        }
        else
        {
            t.position = targetPos;
        }
    }

    /// <summary>将所有活跃随从传送到玩家两侧和侧前方（正前方留空不挡路），阵型跟随面朝方向旋转</summary>
    private static void TeleportFollowers(Vector2 playerPos, Vector2 playerForward, Transform newParent)
    {
        var followers = EnemyFollower.ActiveFollowers;
        int count = followers.Count;
        if (count == 0) return;

        float angle = Mathf.Atan2(playerForward.y, playerForward.x) - Mathf.PI / 2f;
        float cos = Mathf.Cos(angle);
        float sin = Mathf.Sin(angle);

        float halfPi = Mathf.PI / 2f;
        float gapAngle = 0.25f; // 正前方留空约 14°，不挡玩家视线和移动

        for (int i = 0; i < count; i++)
        {
            float t = count > 1 ? (float)i / (count - 1) : -0.5f;

            // 在 -90°~90° 之间分布，但跳过正前方 ±gap 区域
            float rad;
            if (count == 1)
            {
                rad = -halfPi + gapAngle; // 单个随从放左侧
            }
            else if (t <= 0.5f)
            {
                rad = Mathf.Lerp(-halfPi, -gapAngle, t * 2f);   // 左侧到左前方
            }
            else
            {
                rad = Mathf.Lerp(gapAngle, halfPi, (t - 0.5f) * 2f); // 右前方到右侧
            }

            float sideX = Mathf.Sin(rad);
            float forwardY = Mathf.Cos(rad);
            Vector2 localOffset = new Vector2(sideX, forwardY) * 1.2f;

            Vector2 rotatedOffset = new Vector2(
                localOffset.x * cos - localOffset.y * sin,
                localOffset.x * sin + localOffset.y * cos
            );

            Vector2 targetPos = playerPos + rotatedOffset;
            followers[i].transform.SetParent(newParent, true);
            TeleportRigidbody(followers[i].transform, targetPos);
        }
    }

    // ==================== 查询 API ====================

    /// <summary>根据 ID 获取房间</summary>
    public RoomRoot GetRoom(int roomId)
    {
        _roomInstances.TryGetValue(roomId, out var room);
        return room;
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomRoot> GetAdjacentRooms(int roomId)
    {
        var result = new List<RoomRoot>();
        var node = _roomGraph?.GetNode(roomId);
        if (node == null) return result;

        foreach (var conn in node.connections)
        {
            if (_roomInstances.TryGetValue(conn.Key, out var room))
                result.Add(room);
        }
        return result;
    }

    /// <summary>确保所有门的连接正确 (在编辑器修改后调用)</summary>
    public void RefreshPortals()
    {
        SetupPortals();
    }

    // ==================== 辅助 ====================

    private void ClearExistingRooms()
    {
        // 1. 清理已追踪的房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Value != null)
                DestroyImmediate(kvp.Value.gameObject);
        }
        _roomInstances.Clear();

        // 2. 清理残余子物体 (场景中保存的旧房间)
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            var child = transform.GetChild(i).gameObject;
            if (child.GetComponent<RoomRoot>() != null)
                DestroyImmediate(child);
        }

        _roomGraph = null;
        _currentRoom = null;
    }

    /// <summary>在编辑器中重新生成 (通过 Context Menu 调用)</summary>
    [ContextMenu("Regenerate Map")]
    public void RegenerateMap()
    {
        ClearExistingRooms();
        GenerateMap();
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    /// <summary>全局静态事件 — 任意敌人死亡时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemyDied;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                OnAnyEnemyDied?.Invoke(this);
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 统一敌人对外接口，供生成器、技能及其它系统使用。
/// 重构目标是让外部通过接口而非具体 BaseEnemy 类型交互。
/// </summary>
public interface IEnemy : IDamageable, ISkillCaster
{
    /// <summary>用于外部查询或定位的 Transform 引用</summary>
    Transform EnemyTransform { get; }

    /// <summary>敌人是否已死亡</summary>
    bool IsDead { get; }

    /// <summary>是否已被同化为随从（房间/生成器应排除）</summary>
    bool IsAssimilated { get; }

    /// <summary>敌人当前持有的技能实例（只读）</summary>
    IReadOnlyList<SkillInstance> SkillInstances { get; }

    /// <summary>敌人死亡事件（触发时表示该敌人已死亡/即将销毁）</summary>
    event Action OnDied;

    /// <summary>敌人被同化为随从事件（触发时房间/生成器应从存活列表移除）</summary>
    event Action<IEnemy> OnAssimilated;
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("攻击乘区")]
    [Tooltip("攻击力乘区，真实攻击 = 基础攻击 × 此值")]
    [SerializeField] private float attackStrengthMultiplier = 1f;
    [Tooltip("射速乘区，真实射速 = 基础射速 × 此值")]
    [SerializeField] private float shotsPerMinuteMultiplier = 1f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    [Header("进化倾向")]
    [Tooltip("进化倾向：正值=朝向宿主，负值=朝向独特。范围 -100 ~ 100")]
    [SerializeField] private float evolutionTendency = 0f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth>=1 ? maxHealth : 1;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength * attackStrengthMultiplier>=1 ? attackStrength * attackStrengthMultiplier : 1;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / (shotsPerMinute * shotsPerMinuteMultiplier);
    public float ShotsPerMinute => shotsPerMinute * shotsPerMinuteMultiplier;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    /// <summary>进化倾向：正值=朝向宿主（金色），负值=朝向独特（紫色）。范围 -100 ~ 100</summary>
    public float EvolutionTendency => evolutionTendency;

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        // 无敌帧：免疫期间不受到任何伤害
        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 镇痛阻滞：伤害拆分为立即 + 延迟（延迟部分记入池，buff 结束后缓慢扣除）
        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

        // 角色受击 → 屏幕振动 + 全屏红闪
        if (CameraShake.Instance != null)
        {
            CameraShake.Instance.Shake(1f);
            CameraShake.Instance.FlashRed();
        }

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"               => maxHealth,
            "Health"                  => health,
            "MoveSpeed"               => moveSpeed,
            "AttackStrength"          => attackStrength,
            "AttackStrengthMultiplier" => attackStrengthMultiplier,
            "BulletSpeed"             => bulletSpeed,
            "ShotsPerMinute"          => shotsPerMinute,
            "ShotsPerMinuteMultiplier" => shotsPerMinuteMultiplier,
            "ColliderRadius"          => colliderRadius,
            "EvolutionTendency"       => evolutionTendency,
            _                         => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                health = Mathf.Min(health, maxHealth);
                break;
            case "Health":
                health = Mathf.Clamp(value, 0f, maxHealth);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "AttackStrengthMultiplier":
                attackStrengthMultiplier = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinuteMultiplier":
                shotsPerMinuteMultiplier = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            case "EvolutionTendency":
                evolutionTendency = Mathf.Clamp(value, -100f, 100f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 科技树 / 配置接口 ----------

    /// <summary>应用基础配置值（来自 PlayerConfig SO）</summary>
    public void ApplyBaseStats(PlayerConfig config)
    {
        if (config == null) return;

        maxHealth = config.maxHealth;
        moveSpeed = config.moveSpeed;
        attackStrength = config.attackStrength;
        bulletSpeed = config.bulletSpeed;
        shotsPerMinute = config.shotsPerMinute;
        colliderRadius = config.colliderRadius;
        health = maxHealth; // 重置满血

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    /// <summary>叠加科技树加成（在 ApplyBaseStats 之后调用）</summary>
    public void ApplyBonuses(Dictionary<string, float> bonuses)
    {
        if (bonuses == null || bonuses.Count == 0) return;

        foreach (var kvp in bonuses)
        {
            SetStatValue(kvp.Key, GetStatValue(kvp.Key) + kvp.Value);
        }

        // 加成后恢复满血（生命上限可能增加了）
        if (bonuses.ContainsKey("MaxHealth"))
            health = maxHealth;

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        attackStrengthMultiplier = Mathf.Max(attackStrengthMultiplier, 0f);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        shotsPerMinuteMultiplier = Mathf.Max(shotsPerMinuteMultiplier, 0f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
        evolutionTendency = Mathf.Clamp(evolutionTendency, -100f, 100f);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
        else
        {
            // 预热对象池，避免首帧给卡
            ProjectilePool.Prewarm(bulletPrefab, 10);
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 从对象池获取子弹
        GameObject bullet = ProjectilePool.Get(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player, gameObject);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    /// <summary>攻击锁定（架盾/引导技能期间不可普攻）</summary>
    public bool AttackLocked { get; set; }

    /// <summary>移动速度倍率（架盾减速等），默认 1</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>硬直免疫（镇痛阻滞等 buff 期间不受眩晕/硬直）</summary>
    public bool IgnoreStun { get; set; }

    /// <summary>当前移动方向（归一化，供冲刺/位移技能读取）</summary>
    public Vector2 MoveDirection => _moveInput.sqrMagnitude > 0.01f ? _moveInput.normalized : Vector2.zero;

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButton(0) && !AttackLocked)
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed * SpeedMultiplier;
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 玩家管理器 (持久化单例) — 负责动态生成 Player 并跨场景保留。
///
/// 通过 [RuntimeInitializeOnLoadMethod] 在首个场景加载前自动创建，
/// 通过 SceneManager.sceneLoaded 事件在每次场景加载时检测：
/// - 场景中有 Player（Tag="Player"）→ 标记 DontDestroyOnLoad 保留
/// - 场景中无 Player → 从 Player 预制体动态生成
///
/// 依赖: 项目中存在 Tag="Player" 的 Player 预制体 (Assets/Prefab/Player.prefab)
/// 被 MapManager / EnemyCore 通过 GameObject.FindGameObjectWithTag("Player") 自动发现
/// </summary>
public class PlayerManager : MonoBehaviour
{
    public static PlayerManager Instance { get; private set; }

    [Header("Player 预制体")]
    [SerializeField] private GameObject _playerPrefab;

    [Header("出生位置")]
    [SerializeField] private Vector3 _spawnPosition = Vector3.zero;

    /// <summary>场景加载后触发: 参数为 (Player GameObject)</summary>
    public event System.Action<GameObject> OnPlayerReady;

    /// <summary>当前 Player GameObject 引用</summary>
    public GameObject CurrentPlayer { get; private set; }

    // ==================== 生命周期 ====================

    /// <summary>
    /// 在首个场景加载前自动创建 PlayerManager GameObject。
    /// 确保在任何场景加载时 PlayerManager 都已在 DontDestroyOnLoad 中就绪。
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;

        var go = new GameObject("[PlayerManager]");
        go.AddComponent<PlayerManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // Editor: 自动查找 Player 预制体，免去手动配置
        // Build: 需将 Player.prefab 放入 Resources/ 目录
        if (_playerPrefab == null)
        {
            _playerPrefab = ResolvePlayerPrefab();
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    // ==================== 场景加载回调 ====================

    /// <summary>每次场景加载后触发，确保场景中存在 Player</summary>
    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        // Start 场景: 销毁 Player 和统计数据
        if (scene.name == "Start")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            DestroyStatistics();
            return;
        }

        // Result / Winning 结算场景: 销毁 Player，但保留统计数据供 UI 展示
        if (scene.name == "Result" || scene.name == "Winning")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            return;
        }

        // === 游戏场景 ===

        // 确保 GameStatistics 存在
        if (GameStatistics.Instance == null)
        {
            var statsGo = new GameObject("[GameStatistics]");
            statsGo.AddComponent<GameStatistics>();
        }

        var player = GameObject.FindGameObjectWithTag("Player");

        // 已存在 Player —— 优先复用（可能是场景中手动放置的，或是上一场景保留的）
        if (player != null)
        {
            // 首次注册: 标记为 DontDestroyOnLoad 以便跨场景保留
            if (player != CurrentPlayer)
            {
                CurrentPlayer = player;
                DontDestroyOnLoad(player);

                // 跨场景复用时不保留当前位置，重置
                player.transform.position = Vector3.zero;

#if UNITY_EDITOR
                Debug.Log($"[PlayerManager] 复用场景中已有的 Player: '{player.name}', 位置={Vector3.zero}");
#endif
            }
            player.transform.position = Vector3.zero;
        }
        // 无 Player —— 从预制体动态生成
        else
        {
            if (_playerPrefab == null)
            {
                Debug.LogError("[PlayerManager] _playerPrefab 未配置！请在 Inspector 中指定 Player 预制体。");
                return;
            }

            var spawned = Instantiate(_playerPrefab, _spawnPosition, Quaternion.identity);
            spawned.name = "Player";
            DontDestroyOnLoad(spawned);
            CurrentPlayer = spawned;

            // 应用 PlayerConfig 基础值 + 科技树局外加成
            ApplyPlayerConfig(spawned);

#if UNITY_EDITOR
            Debug.Log($"[PlayerManager] 动态生成 Player，位置={spawned.transform.position}");
#endif
        }

        // 绑定 Player 到统计系统
        GameStatistics.Instance?.BindPlayer(CurrentPlayer);

        OnPlayerReady?.Invoke(CurrentPlayer);
    }

    /// <summary>销毁统计数据</summary>
    private static void DestroyStatistics()
    {
        if (GameStatistics.Instance != null)
        {
            if (Application.isPlaying)
                Destroy(GameStatistics.Instance.gameObject);
            else
                DestroyImmediate(GameStatistics.Instance.gameObject);
        }
    }

    // ==================== 辅助 ====================

    /// <summary>应用 PlayerConfig 基础值 + 科技树局外加成（仅在动态生成 Player 时调用）</summary>
    private void ApplyPlayerConfig(GameObject player)
    {
        if (player == null) return;

        var stats = player.GetComponent<PlayerStats>();
        if (stats == null) return;

        // 加载 PlayerConfig
        var config = Resources.Load<PlayerConfig>("PlayerConfig");
        if (config != null)
        {
            stats.ApplyBaseStats(config);
        }
        else
        {
            Debug.LogWarning("[PlayerManager] 未找到 PlayerConfig，Player 将使用预制体上的默认值。路径: Resources/PlayerConfig");
        }

        // 叠加科技树加成
        var mgr = TechTreeManager.Instance;
        if (mgr != null)
        {
            var bonuses = mgr.GetAllBonuses();
            if (bonuses != null && bonuses.Count > 0)
            {
                stats.ApplyBonuses(bonuses);
#if UNITY_EDITOR
                Debug.Log($"[PlayerManager] 已应用科技树加成: {bonuses.Count} 项");
#endif
            }
        }
    }

    /// <summary>自动查找 Player 预制体引用</summary>
    private static GameObject ResolvePlayerPrefab()
    {
#if UNITY_EDITOR
        // Editor 模式: 通过 AssetDatabase 按路径加载
        var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab");
        if (prefab != null)
        {
            Debug.Log("[PlayerManager] 已自动加载 Player 预制体: Assets/Prefab/Player.prefab");
            return prefab;
        }
        Debug.LogWarning("[PlayerManager] 未找到 Assets/Prefab/Player.prefab，请确认路径正确。");
#endif

        // Build 模式: 从 Resources 目录加载
        var resourcePrefab = Resources.Load<GameObject>("Player");
        if (resourcePrefab != null)
        {
            Debug.Log("[PlayerManager] 已从 Resources 加载 Player 预制体。");
            return resourcePrefab;
        }

        Debug.LogError(
            "[PlayerManager] 无法找到 Player 预制体！\n" +
            "  - Editor: 请确认 Assets/Prefab/Player.prefab 存在\n" +
            "  - Build: 请将 Player.prefab 放入任意 Resources/ 目录下");
        return null;
    }
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 召唤技能：在施法者周围随机位置生成单位。
/// 根据施法者阵营自动选择预制体池、Tag 与目标。
/// </summary>
[CreateAssetMenu(fileName = "SummonEffect", menuName = "Game/Skill Effect/Summon")]
public class SummonSkillEffect : SkillEffectBase
{
    [Header("召唤 — 敌方单位池（Boss/Enemy 释放时使用）")]
    [Tooltip("生成的单位 Tag=Enemy，攻击玩家")]
    public GameObject[] enemyMinionPrefabs;

    [Header("召唤 — 友方单位池（Player 释放时使用）")]
    [Tooltip("生成的单位 Tag=Player，攻击敌人")]
    public GameObject[] playerMinionPrefabs;

    [Header("参数")]
    [Tooltip("召唤数量")]
    public int count = 3;

    [Tooltip("生成半径 (围绕施法者)")]
    public float spawnRadius = 4f;

    [Tooltip("生成间隔 (秒)")]
    public float spawnInterval = 0.3f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;
        mono.StartCoroutine(SummonRoutine(caster, ownerType));
    }

    private System.Collections.IEnumerator SummonRoutine(ISkillCaster caster, Projectile.OwnerType ownerType)
    {
        GameObject[] pool = ownerType == Projectile.OwnerType.Player
            ? playerMinionPrefabs
            : enemyMinionPrefabs;

        if (pool == null || pool.Length == 0)
        {
            Debug.LogWarning("SummonSkillEffect: 无可用预制体池");
            yield break;
        }

        string targetTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        string selfTag   = ownerType == Projectile.OwnerType.Player ? "Player" : "Enemy";

        Vector2 center = caster.CasterTransform.position;
        Transform parent = caster.CasterTransform.parent;

        for (int i = 0; i < count; i++)
        {
            Vector2 offset = Random.insideUnitCircle * spawnRadius;
            Vector2 spawnPos = center + offset;

            GameObject prefab = pool[Random.Range(0, pool.Length)];
            if (prefab == null) continue;

            var go = Object.Instantiate(prefab, spawnPos, Quaternion.identity, parent);
            go.name = $"Summon_{ownerType}_{i}_{prefab.name}";

            // 阵营标记
            go.tag = selfTag;

            // 设置敌人 Core 的初始目标
            var core = go.GetComponent<EnemyCore>();
            if (core != null)
            {
                var target = FindNearestTarget(spawnPos, targetTag);
                if (target != null)
                    core.PlayerTarget = target; // 字段名是 PlayerTarget，但实际是"攻击目标"
            }

            yield return new WaitForSeconds(spawnInterval);
        }
    }

    private static Transform FindNearestTarget(Vector2 origin, string targetTag)
    {
        var gos = GameObject.FindGameObjectsWithTag(targetTag);
        if (gos == null || gos.Length == 0) return null;

        Transform best = null;
        float bestDist = float.MaxValue;
        foreach (var go in gos)
        {
            float d = Vector2.SqrMagnitude((Vector2)go.transform.position - origin);
            if (d < bestDist)
            {
                bestDist = d;
                best = go.transform;
            }
        }
        return best;
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    /// <summary>投射物阵营（公开只读，供地面区域等组件读取）</summary>
    public OwnerType Owner => _owner;

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <summary>是否被时停冻结</summary>
    public bool IsFrozen { get; private set; }
    private float _frozenLifetimeRemain;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;
        IsFrozen = false;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>冻结投射物（停止移动+暂停生命周期）</summary>
    public void Freeze()
    {
        if (!_isInitialized || IsFrozen) return;
        IsFrozen = true;
        // 记录剩余生命时间并取消自动回收
        _frozenLifetimeRemain = Mathf.Max(lifeTime * 0.5f, 1f);
        CancelInvoke(nameof(ReturnToPool));
    }

    /// <summary>解冻投射物，恢复移动和生命周期</summary>
    public void Unfreeze()
    {
        if (!_isInitialized || !IsFrozen) return;
        IsFrozen = false;
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), _frozenLifetimeRemain);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized || IsFrozen) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";

        // 动情腺溢散（互相攻击）：敌人投射物命中其他敌人时，若目标带混淆 debuff 则也造成伤害
        bool confusionHit = false;
        if (_owner == OwnerType.Enemy && other.CompareTag("Enemy"))
        {
            var buffMgr = other.GetComponent<BuffManager>();
            confusionHit = buffMgr != null && buffMgr.HasBuff("gland_confusion");
        }

        if (!other.CompareTag(targetTag) && !confusionHit) return;

        // 护盾拦截：目标架盾中则挡住弹幕（不造成伤害）
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
            ReturnToPool();
            return;
        }

        // 因子掠夺：命中目标后先偷取其增益 buff（目标存活时才有 buff 可偷）
        var plunder = GetComponent<BuffPlunderOnHit>();
        if (plunder != null)
            plunder.TryPlunder(other.gameObject);

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 投射物对象池 — 按 prefab 分组，池化复用 GameObject。
/// </summary>
public static class ProjectilePool
{
    private static readonly Dictionary<int, Queue<GameObject>> _pools = new();

    /// <summary>从池中取出，池空则 Instantiate，自动标记来源 prefab</summary>
    public static GameObject Get(GameObject prefab, Vector3 position, Quaternion rotation)
    {
        int key = prefab.GetInstanceID();
        if (!_pools.TryGetValue(key, out var queue))
            queue = _pools[key] = new Queue<GameObject>();

        GameObject obj;
        if (queue.Count > 0)
        {
            obj = queue.Dequeue();
            var t = obj.transform;
            t.position = position;
            t.rotation = rotation;
            obj.SetActive(true);
        }
        else
        {
            obj = Object.Instantiate(prefab, position, rotation);
            obj.name = prefab.name;
            // 贴上来源标记
            var marker = obj.AddComponent<PoolMarker>();
            marker.prefabId = key;
        }

        foreach (var p in obj.GetComponents<IPoolable>())
            p.OnSpawn();

        return obj;
    }

    /// <summary>归还实例到池（停用+入队）</summary>
    public static void Return(GameObject instance)
    {
        if (instance == null) return;

        foreach (var p in instance.GetComponents<IPoolable>())
            p.OnReturn();

        instance.transform.SetParent(null);
        instance.SetActive(false);

        var marker = instance.GetComponent<PoolMarker>();
        if (marker != null)
        {
            int key = marker.prefabId;
            if (!_pools.TryGetValue(key, out var queue))
                queue = _pools[key] = new Queue<GameObject>();
            queue.Enqueue(instance);
        }
        else
        {
            Object.Destroy(instance);
        }
    }

    /// <summary>预热（pool 已有同级实例则跳过）</summary>
    public static int Prewarm(GameObject prefab, int count)
    {
        int key = prefab.GetInstanceID();
        if (!_pools.TryGetValue(key, out var queue))
            queue = _pools[key] = new Queue<GameObject>();

        int created = 0;
        while (queue.Count < count && created < count)
        {
            var obj = Object.Instantiate(prefab);
            obj.name = prefab.name;
            obj.SetActive(false);
            queue.Enqueue(obj);
            if (obj.GetComponent<PoolMarker>() == null)
                obj.AddComponent<PoolMarker>().prefabId = key;
            created++;
        }
        return created; // 实际创建数（已存在则不创建）
    }

    /// <summary>清空</summary>
    public static void Clear()
    {
        foreach (var q in _pools.Values)
            while (q.Count > 0) Object.Destroy(q.Dequeue());
        _pools.Clear();
    }
}

/// <summary>池化生命周期回调</summary>
public interface IPoolable
{
    void OnSpawn();      // Get 取出时
    void OnReturn();     // Return 归还前
}

/// <summary>内部标记：记录此对象源自哪个 prefab</summary>
public class PoolMarker : MonoBehaviour
{
    public int prefabId;
}

using UnityEngine;

/// <summary>
/// 通用伤害免疫组件 — 挂在角色身上，授予一段时间的无敌（免疫所有伤害）。
/// 任何伤害入口（PlayerStats / EnemyHealth 的 TakeDamage）都应检查 IsImmune。
/// 供"格挡后无敌帧"等机制复用。
/// </summary>
public class DamageImmunity : MonoBehaviour
{
    private float _remainingTime;

    /// <summary>当前是否免疫伤害</summary>
    public bool IsImmune => _remainingTime > 0f;

    /// <summary>剩余免疫时间（秒）</summary>
    public float RemainingTime => _remainingTime;

    /// <summary>授予无敌（刷新/覆盖现有免疫时长）</summary>
    public void GrantImmunity(float duration)
    {
        _remainingTime = Mathf.Max(_remainingTime, duration);
    }

    private void Update()
    {
        if (_remainingTime > 0f)
